// The sky that comes with Sound Studio: the Backdrop's picture until another
// is chosen, and what the × goes back to. It is folded into a script as a
// data URL so the page can use it when opened straight from a file — a
// sibling image file would taint the canvas there, and recordings and the
// lyric colours need the canvas clean. 952 x 1260, WebP.
window.BUILT_IN_SKY = { name: 'Purple sky', credit: 'Image: NASA/ESA',
  data: 'data:image/webp;base64,' };
